struct OrderMessage: Codable {                   // the message contract
    let id: String
    let customerId: String
    let totalMinor: Int64
    enum CodingKeys: String, CodingKey { case id; case customerId = "customer_id"; case totalMinor = "total_minor" }
}
extension OrderMessage {                         // the mapper, next to the message
    init(_ o: Order) { self.init(id: o.id, customerId: o.customer.id, totalMinor: o.total.minorUnits) }
}
